+            .map_err(|e| format!("verify failed for artifact {i}: {e}"))?;
+        let computed = accepted_artifact_digest(artifact)
+            .map_err(|e| format!("accepted_artifact_digest failed for {i}: {e}"))?;
+        if computed != artifact.digest {
