        .compiled_ir(digest)
        .map_err(|e| format!("compiled_ir readback failed: {e}"))?
        .ok_or_else(|| "artifact record not found".to_string())?;
    if record.digest != digest {
        return Err("record digest does not match expected".to_string());
    }
