        postcard::from_bytes(&record.ir).map_err(|e| format!("postcard decode failed: {e}"))?;
    if accepted_artifact_digest(&decoded)
        .map_err(|e| format!("accepted_artifact_digest failed: {e}"))?
        != decoded.digest
