    let next = submit_artifact(&journal, &workflow, RuntimePolicy::Relaxed)
        .map_err(|e| format!("seq 9 submission failed: {e}"))?;
    if next.accepted_at_seq.get() != 9 {
        return Err(format!(
            "next artifact should have seq 9, got {}",
            next.accepted_at_seq.get()
        ));
    }

    Ok(())
}

